const dictionaries = { ru: {}, en, kk } satisfies Record<Language, Record<string, string>>;
interface LanguageContextValue { language: Language; setLanguage: (language: Language) => void; t: (russian: string) => string; locale: string }
const LanguageContext = createContext<LanguageContextValue>({ language: 'ru', setLanguage: () => undefined, t: (value) => value, locale: 'ru-RU' });

function deviceLanguage(): Language {
  try {
    const tag = Intl.DateTimeFormat().resolvedOptions().locale.toLowerCase();
    if (tag.startsWith('kk')) return 'kk';
    if (tag.startsWith('ru')) return 'ru';
  } catch {
    // Intl may be unavailable on some runtimes; fall back to English.
  }
  return 'en';
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguageState] = useState<Language>(deviceLanguage);
  useEffect(() => {
    AsyncStorage.getItem(LANGUAGE_KEY).then((saved) => {
      if (saved === 'kk' || saved === 'ru' || saved === 'en') setLanguageState(saved);
    }).catch(() => undefined);
  }, []);
  // Only an explicit choice is persisted, so the default keeps following the device language.
  const setLanguage = useCallback((next: Language) => {
    setLanguageState(next);
    AsyncStorage.setItem(LANGUAGE_KEY, next).catch(() => undefined);
  }, []);
  const t = useCallback((russian: string) => language === 'ru' ? russian : dictionaries[language][russian] ?? russian, [language]);
  const locale = language === 'kk' ? 'kk-KZ' : language === 'en' ? 'en-US' : 'ru-RU';
  const value = useMemo(() => ({ language, setLanguage, t, locale }), [language, setLanguage, t, locale]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() { return useContext(LanguageContext); }
export const LANGUAGE_OPTIONS: { code: Language; label: string }[] = [
  { code: 'kk', label: 'Қазақша' }, { code: 'ru', label: 'Русский' }, { code: 'en', label: 'English' },
];
